   60	    public function plan(int $playerId, ?PlayerService $player = null): QueueableBuilding|QueueableResearch|null
   61	    {
   62	        return $this->steps($playerId, $player, 1)[0] ?? null;
   63	    }
   64	
   65	    /**
   66	     * Every queue a player would fill in one login: at most one building per planet, because each planet
   67	     * pays from its own stock and has its own build queue, and at most one technology, because the
   68	     * lab is one queue for the account. The order is plan()'s, so the first step is the one plan()
   69	     * returns.
   70	     *
   71	     * @return list<QueueableBuilding|QueueableResearch>
   72	     */
   73	    public function steps(int $playerId, ?PlayerService $player = null, int $limit = PHP_INT_MAX): array
   74	    {
   75	        // An account the module does not manage has no policy to apply, so it gets no capability.
   76	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   77	        if ($profile === null) {
   78	            return [];
   79	        }
   80	
   81	        // The module owns profile rows; the host owns accounts. A profile can outlive its account or
   82	        // be written by a fixture, and loading an account the host does not have throws -- so the
   83	        // precondition is asked here rather than discovered in the host service.
   84	        if (!User::query()->whereKey($playerId)->exists()) {
   85	            return [];
   86	        }
   87	
   88	        // Refresh every planet's live balance once: the candidate pass reads stored amounts and
   89	        // energy, and a balance read stale is exactly the balance the queue later cancels on. The
   90	        // refresh stays in memory -- the observation path must not write.
   91	        $planets = ($player ?? $this->playerServiceFactory->make($playerId, true))->planets->all();
   92	        foreach ($planets as $planet) {
   93	            $planet->updateResources(false);
   94	            $planet->updateResourceProductionStats(false);
   95	            $planet->updateResourceStorageStats(false);
   96	        }
   97	
   98	        $passes = $this->passes($profile);
   99	
  100	        // What every planet is holding back, once per session: reading it walks the same candidate
  101	        // lists the passes do, so asking again inside each pass would repeat a planet's whole economy.
  102	        // It is also what keeps this list honest: the cohort reads "buildable" from exactly these
  103	        // steps, so a planet whose pile the goal reserves must not be offered here -- otherwise the
  104	        // read-out says buildable while the account rightly saves, and the invariant flags a saver
  105	        // for behaving as designed.
  106	        $goals = [];
  107	        foreach ($planets as $planet) {
  108	            $goals[$planet->getPlanetId()] = $this->savingsGoal($planet, $profile);
  109	        }
  110	
  111	        // A planet that holds nothing while a sibling already stands a wall spends its balance on the
  112	        // economy at every login and never reaches the price of the unit its wall waits on: the
  113	        // cheapest mine upgrade is always the cheaper order, so the planet sits at zero defence
  114	        // beside the account's wall for as long as it plays (QUAL-003). Its build queue belongs to
  115	        // the wall until the wall stands -- the wall's own prerequisites, and nothing else -- so what
  116	        // those steps leave is still there when the unit planner prices the wall order it places
  117	        // ahead of them.
  118	        $awaitsWall = [];
  119	        foreach ($planets as $planet) {
  120	            $awaitsWall[$planet->getPlanetId()] = $this->facilityChain->nakedBesideWalled($planet);
  121	        }
  122	
  123	        $steps = [];
  124	        foreach ($passes as $pass => $candidates) {
  125	            foreach ($planets as $planet) {
  126	                if (count($steps) >= $limit) {
  127	                    return array_values($steps);
  128	                }
  129	
  130	                if ($awaitsWall[$planet->getPlanetId()] && $pass !== self::WALL_STEP) {
  131	                    continue;
  132	                }
  133	
  134	                $steps = $this->withStep($steps, $planet, $profile, $candidates, $goals[$planet->getPlanetId()], $pass === self::WALL_STEP);
  135	            }
  136	        }
  137	
  138	        return array_values($steps);
  139	    }
  140	
  141	    /**
  142	     * The candidate lists in the order the planner tries them. A warehouse about to overflow stops
  143	     * that planet producing, so its pass runs across every planet before any routine step; a full
  144	     * warehouse (E7) is a spend signal and comes next; then the routine economy: energy before it
  145	     * throttles, the chain's facilities, the fastest-paying mine. Public so a read-out explains a
  146	     * planet with the same lists the decision used.
  147	     *
  148	     * @return array<string, callable(PlanetService): list<BuildCandidate>>
  149	     */
  150	    public function passes(AiProfile $profile): array
  151	    {
  152	        return [
  153	            // A planet holding no defence while a sibling already stands a wall is past the
  154	            // account's opening with a sibling walled everywhere else: the facilities the wall
  155	            // itself waits on come before the economy, so the planet is not left naked behind a
  156	            // stock it is busy spending (QUAL-003). The step is the same shape as a wall order: a
  157	            // saving the economy is holding back does not veto it, because a planet with no wall is
  158	            // the state the account is fixing, not a step it chooses between (QUAL-003).
  159	            'wall' => fn (PlanetService $planet): array => $this->facilityChain->wallPending($planet),
  160	            'storage' => fn (PlanetService $planet): array => $this->economyUpgrades->storage($planet, $profile),
  161	            'surplus' => fn (PlanetService $planet): array => $this->economyUpgrades->spendSurplus($planet, $profile),
  162	            'routine' => fn (PlanetService $planet): array => [
  163	                ...$this->energyCapacity->pending($planet),
  164	                ...$this->facilityChain->pending($planet),
  165	                ...$this->economyUpgrades->storageForPrice($planet, $profile),
  166	                ...$this->economyUpgrades->production($planet, $profile),
  167	            ],
  168	        ];
  169	    }
  170	
  171	    /**
  172	     * The build queue and the lab run side by side, so a planet's building and the account's one
  173	     * technology are separate steps: a planet whose best candidate is a technology still builds.
  174	     *
  175	     * @param array<int|string, QueueableBuilding|QueueableResearch> $steps
  176	     * @param callable(PlanetService): list<BuildCandidate> $pass
  177	     * @return array<int|string, QueueableBuilding|QueueableResearch>
  178	     */
  179	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal, bool $wall = false): array
  180	    {
  181	        $candidates = $pass($planet);
  182	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
  183	
  184	        // The candidate list is in priority order, so whichever queue its first entry belongs to is tried first.
  185	        $queues = [$planet->getPlanetId() => false, self::LAB_STEP => true];
  186	        if ($candidates !== [] && $isResearch($candidates[0])) {
  187	            $queues = array_reverse($queues, true);
  188	        }
  189	
  190	        foreach ($queues as $key => $research) {
  191	            if (isset($steps[$key])) {
  192	                continue;
  193	            }
  194	
  195	            $step = $this->firstQueueable($planet, $profile, array_values(array_filter($candidates, static fn (BuildCandidate $candidate): bool => $isResearch($candidate) === $research)), $wall ? null : $goal);
  196	            if ($step !== null) {
  197	                $steps[$key] = $step;
  198	            }
  199	        }
  200	
  201	        return $steps;
  202	    }
  203	
  204	    /**
  205	     * The first candidate this planet can actually queue, or null when none of them is legal.
  206	     *
  207	     * @param list<BuildCandidate> $candidates
  208	     */
  209	    private function firstQueueable(PlanetService $planet, AiProfile $profile, array $candidates, ?SavingsGoal $goal): QueueableBuilding|
