  399	    /**
  400	     * @param array<string, GameObject> $producers
  401	     * @return list<BuildCandidate> cheapest first, the same convention as the capacity rule
  402	     */
  403	    private function producerSteps(array $producers, PlanetService $planet): array
  404	    {
  405	        $objects = array_values($producers);
  406	
  407	        usort($objects, static fn (GameObject $left, GameObject $right): int =>
  408	            ObjectService::getObjectPrice($left->machine_name, $planet)->sum()
  409	            <=> ObjectService::getObjectPrice($right->machine_name, $planet)->sum());
  410	
  411	        return array_map(static fn (GameObject $object): BuildCandidate => app()->makeWith(BuildCandidate::class, [
  412	            'buildingId' => $object->id,
  413	            'reason' => 'chain:' . $object->machine_name,
  414	        ]), $objects);
  415	    }
