  417	    /**
  418	     * How far this account already is with one prerequisite.
  419	     *
  420	     * The host keeps a planet's levels on the planet and a technology's on the player, so asking the
  421	     * planet for a technology answers zero every time and would offer the same step forever.
  422	     */
  423	    private function currentLevel(PlanetService $planet, string $machineName): int
  424	    {
  425	        $isResearch = ObjectService::getObjectByMachineName($machineName)->type === GameObjectType::Research;
  426	
  427	        if (!$isResearch) {
  428	            return $planet->getObjectLevel($machineName);
  429	        }
  430	
  431	        // A planet always has an owner on the host; the nullable signature is the
  432	        // host's, so a missing player reads as level zero rather than crashing a
  433	        // decision on data the host itself would not normally be without.
  434	        return $planet->getPlayer()?->getResearchLevel($machineName) ?? 0;
  435	    }
  436	
  437	    /**
  438	     * The facilities the host's own smallest defence unit requires, or none when this planet does not
  439	     * need them.
  440	     *
  441	     * A planet needs them exactly when it holds no defence while a sibling of the same account
  442	     * already stands one: that is the account past its opening, with a wall it built everywhere it
  443	     * could reach, so the reasons the unit planner has for waiting no longer apply and the facility
  444	     * that gates the wall is as much a prerequisite as a laboratory gating a technology.
  445	     *
  446	     * @return array<string, int>
  447	     */
  448	    private function wallPrerequisites(PlanetService $planet): array
  449	    {
  450	        if (! $this->nakedBesideWalled($planet)) {
  451	            return [];
  452	        }
  453	
  454	        $unit = $this->smallestDefenceUnit();
  455	
  456	        return $unit === null ? [] : ObjectService::getRecursiveRequirements($unit->machine_name);
  457	    }
  458	
  459	    /**
  460	     * Whether this planet holds nothing while a sibling of the same account holds something.
  461	     *
  462	     * "Holds" is the unit planner's own answer -- built plus already paid for in the yard -- and not the
  463	     * built-only count: the account has left its opening the moment its first wall order is placed, so the
  464	     * sibling's bare neighbour is reached from that login rather than one login behind a wall that is
  465	     * already standing in the queue (QUAL-003: the two planners disagreed about when a wall stands).
  466	     */
  467	    public function nakedBesideWalled(PlanetService $planet): bool
  468	    {
  469	        $defence = app(DefenseNeedEvaluator::class);
  470	
  471	        if ($defence->standingUnits($planet) > 0) {
  472	            return false;
  473	        }
  474	
  475	        $player = $planet->getPlayer();
  476	        if ($player === null) {
  477	            return false;
  478	        }
  479	
  480	        foreach ($player->planets->all() as $sibling) {
  481	            if ($sibling->getPlanetId() !== $planet->getPlanetId() && $defence->standingUnits($sibling) > 0) {
  482	                return true;
  483	            }
  484	        }
  485	
  486	        return false;
  487	    }
