test('a walled homeworld with a rich stock reaches the colony that owns nothing', function (): void {
    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();

    $situation = Situation::of($this)
        ->level('robot_factory', 2)
        ->level('shipyard', 4)
        ->defence('rocket_launcher', 1_200)
        ->colony()
        ->resources(50_000_000, 50_000_000, 50_000_000);

    $situation->day();", "new_string": "// QUAL-003's live shape (invariant:NAKED_BESIDE_WALLED, aspect:shipyard): the cohort read counts the
// defence the host has *built*, and the planets it read as naked are the near-zero-production ones. The
// colony here is funded by nothing but its own mines, so neither the wall order nor the yard it waits on
// can be paid out of a sibling's stock: the account has to keep the colony's economy buying mines until
// the yard is affordable, rather than spend every login on a wall order it cannot pay for.
test('a walled homeworld reaches the colony that has to fund its own yard', function (): void {
    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();

